<template><view class="page safe-bottom"><view class="review-card surface"><text class="section-title">服务评价</text><text class="service-name">{{ serviceName }}</text><view class="stars"><text v-for="item in 5" :key="item" class="star" :class="{ active: item <= rating }" @click="rating = item">★</text></view><textarea v-model="content" class="textarea" placeholder="分享本次服务体验，帮助我们做得更好" maxlength="300" /><button class="primary-button" :loading="submitting" @click="submit">提交评价</button></view></view></template>
<script setup>
import { ref } from 'vue'; import { submitReview } from '@/api/service'; const rating = ref(5); const content = ref(''); const submitting = ref(false); const serviceName = ref('本次家政服务'); async function submit () { if (!content.value.trim()) return uni.showToast({ title: '请填写评价内容', icon: 'none' }); submitting.value = true; try { await submitReview({ orderId: getCurrentPages().at(-1)?.options?.id, rating: rating.value, content: content.value }); uni.showToast({ title: '评价成功', icon: 'success' }); setTimeout(() => uni.navigateBack(), 600) } catch (e) { uni.showToast({ title: e.message || '提交失败', icon: 'none' }) } finally { submitting.value = false } }
</script><style lang="scss" scoped>
.review-card{padding:34rpx}.service-name{display:block;margin-top:18rpx;color:$app-muted;font-size:26rpx}.stars{display:flex;gap:18rpx;margin:32rpx 0}.star{color:#d9e0ea;font-size:58rpx}.star.active{color:#f5b83d}.textarea{width:100%;height:240rpx;box-sizing:border-box;padding:20rpx;border:1rpx solid $app-border;border-radius:14rpx;color:$app-text;font-size:28rpx}.primary-button{width:100%;margin-top:30rpx}
</style>
